#include<bits/stdc++.h>
#define int long long
using namespace std;
int ans=0;
const int mod=998244353;
int a[3333][3333];
string s;
int dfs(int p,int l,int r){
//	cout<<s<<endl;
	if(p==s.size()){
		if(l==r){
			return 1;
		}
		return 0;
	}else if(a[p][l]!=-1){
		return a[p][l];
	}else{
		if(s[p]!='?'){
			if(s[p]=='('){
				int x=dfs(p+1,l+1,r);
				x%=mod;
				a[p][l]=x;
				return x;
			}else{
				int x=dfs(p+1,l,r+1);
				x%=mod;
				a[p][l]=x;
				return x;
			}
		}else{
			int x=0;
			if(r<l){
			
				s[p]=')';
				x+=dfs(p+1,l,r+1);
				s[p]='?';
			}
			s[p]='(';
			x+=dfs(p+1,l+1,r);
			s[p]='?';
			x%=998244353;
			a[p][l]=x;
			return x;
		}
	}
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin>>s;
	memset(a,-1,sizeof(a));
	cout<<dfs(0,0,0);
    return 0;
}
